CREATE OR REPLACE FUNCTION refuse_untraceable_park() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW.status IS DISTINCT FROM 'deferred' THEN RETURN NEW; END IF;
  IF COALESCE(btrim(NEW.handler_agent),'') = '' THEN RETURN NEW; END IF;   -- bugs_closed/077 shelf
  IF TG_OP='UPDATE' AND OLD.status IS NOT DISTINCT FROM 'deferred' THEN RETURN NEW; END IF;
  v_by  := COALESCE(NEW.spec->>'parked_by',     NEW.result->>'parked_by');
  v_why := COALESCE(NEW.spec->>'parked_reason', NEW.result->>'parked_reason');
  IF COALESCE(btrim(v_by),'')='' OR COALESCE(btrim(v_why),'')='' THEN
    RAISE EXCEPTION 'WORK_ITEM_PARK_PROVENANCE_REFUSED: ...' USING HINT='DROP TRIGGER trg_site_work_items_park_provenance ON site_work_items;';
  END IF;
  RETURN NEW;
END $fn$;
CREATE TRIGGER trg_site_work_items_park_provenance BEFORE INSERT OR UPDATE ON site_work_items FOR EACH ROW EXECUTE FUNCTION refuse_untraceable_park();

DROP TRIGGER IF EXISTS trg_site_work_items_park_provenance ON site_work_items;
DROP FUNCTION IF EXISTS refuse_untraceable_park();
